M={m['id']:m for m in json.loads((S/'data/editorial-media.json').read_text(encoding='utf-8'))}
def link(url,text):return f'<a href="{url}" target="_blank" rel="noopener">{text} ↗</a>'
def photo(id,caption=None,cls='',eager=False):
 m=M[id];source='sources.html#photography' if m.get('origin')=='user' else m['source'];return f'''<figure class="editorial-photo {cls}"><img src="{m['image']}" alt="{html.escape(m['alt'])}" width="{m['width']}" height="{m['height']}" loading="{'eager' if eager else 'lazy'}"><figcaption>{caption or m['title']}<span>{link(source,m['author'])}</span></figcaption></figure>'''
nav=[('index.html','Главная'),('brands.html','Бренды'),('lookbook.html','Галерея'),('men.html','Мужчинам'),('leggings.html','Легинсы'),('business.html','Индустрия'),('guide.html','Как выбрать')]
def page(file,title,description,body,scripts=''):
 n=''.join(f'<a href="{url}"'+(' class="active" aria-current="page"' if file==url else '')+f'>{label}</a>' for url,label in nav)
 text=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — ТОНКО</title><meta name="description" content="{description}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="https://unpkg.com/@phosphor-icons/web@2.1.1/src/regular/style.css"><link rel="stylesheet" href="portal.css"><link rel="stylesheet" href="features.css"><link rel="stylesheet" href="tonko.css"><link rel="stylesheet" href="editorial.css"><meta property="og:title" content="{title} — ТОНКО"><meta property="og:image" content="https://big-arch.github.io/TOHKO/assets/editorial/wolford-1.jpg"></head><body><a class="portal-skip" href="#content">Перейти к содержимому</a><header class="portal-header"><div class="portal-nav-shell"><a class="portal-logo" href="index.html" aria-label="ТОНКО, главная">ТОНКО</a><nav class="portal-nav" id="portal-nav" aria-label="Основная навигация">{n}<a href="search.html">Поиск</a></nav><a class="portal-nav-action" href="wardrobe.html">Избранное</a><button class="portal-menu-toggle" type="button" data-nav-toggle aria-controls="portal-nav" aria-expanded="false" aria-label="Открыть меню"><span></span><span></span></button></div></header><main id="content">{body}</main><footer class="portal-footer"><div class="portal-container editorial-footer"><div><a href="index.html" class="editorial-footer-name">ТОНКО</a><p>Колготки, легинсы и культура тонкого трикотажа.<br>Смотреть внимательно. Выбирать осознанно.</p></div><div><a href="history.html">История</a><a href="nylon.html">Материалы</a><a href="videos.html">Видео</a><a href="sources.html">Источники и фото</a></div><div><a href="atlas.html">Посадка и уход</a><a href="compare.html">Сравнение моделей</a><a href="privacy.html">Конфиденциальность</a><a href="terms.html">Условия</a></div></div><div class="portal-container portal-footer-bottom"><span>© 2026 ТОНКО</span><span>Независимый проект о вещах и людях.</span></div></footer>{scripts}<script src="portal.js"></script><script src="tonko.js"></script><script src="editorial.js"></script></body></html>'''
 (S/file).write_text(text,encoding='utf-8')
def intro(kicker,title,lead):return f'<section class="editorial-intro portal-container"><p class="portal-eyebrow">{kicker}</p><h1>{title}</h1><p class="editorial-lead">{lead}</p></section>'
def chapter(id,title,body):return f'<section class="reading-section" id="{id}"><h2>{title}</h2>{body}</section>'
def p(t):return '<p>'+t+'</p>'
def toc(items):return '<nav class="chapter-nav" aria-label="Содержание">'+''.join(f'<a href="#{i}">{t}</a>' for i,t in items)+'</nav>'
def reading(body,aside):return '<div class="portal-container reading-layout"><article class="reading-body">'+body+'</article><aside class="reading-aside">'+aside+'</aside></div>'
def sources(entries):return '<div class="article-sources"><h2>Источники и дальнейшее чтение</h2><ol>'+''.join('<li>'+link(u,t)+'</li>' for u,t in entries)+'</ol><p>Проверено 15 ноября 2026. Свойства конкретной модели уточняйте в её карточке.</p></div>'

