cases=[
('blakely','Сара Блейкли','SPANX','sara-blakely','От неудобной вещи — к новой категории',
'В 1998 году Блейкли обрезала стопы у корректирующих колготок, чтобы носить их с открытой обувью. На разработку продукта ушло ещё два года: SPANX вышел на рынок в 2000-м. История компании связывает запуск с конкретной проблемой гардероба, а не с изобретением нового полимера.',
'В октябре 2021 года Blackstone объявила о покупке контрольной доли при оценке SPANX в 1,2 млрд долларов. В сообщении инвестора указаны 5 тысяч долларов стартовых сбережений основательницы; после сделки она сохраняла существенную долю. Оценка компании в сделке не равна выручке или личным деньгам основательницы.',
'Редакционный разбор: понятная проблема помогает объяснить товар одним предложением. Но между удачным прототипом и бизнесом стоят испытания посадки, производство, размерный ряд, дистрибуция и доверие. Расширение в легинсы и одежду имеет смысл, когда покупатели уже понимают обещание бренда.',
'Что проверять: повторные покупки, возвраты по посадке, зависимость от одного продукта и стоимость привлечения покупателя.',
[('https://spanx.com/en-gb/pages/about-us','История SPANX'),('https://www.blackstone.com/news/press/blackstone-buys-majority-stake-in-spanx-inc/','Blackstone: условия сделки, 20.10.2021')]),
('veronesi','Сандро Веронези','Calzedonia / Oniverse','oniverse','Система важнее одного бестселлера',
'Группа, основанная в 1986 году Сандро Веронези, выросла вокруг специализированной розницы. На корпоративном сайте Oniverse описывает контроль полного цикла: от идеи и производства до распределения и магазинов. Calzedonia — один из брендов группы, а не синоним всей компании.',
'Oniverse сообщает о 3,5 млрд евро оборота за 2024 год; 62% пришлось на рынки за пределами Италии. Это показатели всей группы, включая другие направления. Они не описывают отдельно продажи колготок Calzedonia и не являются прибылью.',
'Редакционный разбор: сеть магазинов позволяет одинаково показывать коллекцию и давать покупателю понятный выбор. Собственная операционная система помогает масштабировать разные бренды. Обратная сторона — аренда, запасы по размерам и цветам, логистика и сложность управления сетью.',
'Что проверять: продажи сопоставимых магазинов, оборачиваемость запасов, долю уценки и различия между собственной розницей и партнёрской сетью.',
[('https://www.oniverse.it/en/the-group/who-we-are','Oniverse: о группе'),('https://www.oniverse.it/en/the-group/oniverse-in-the-world','Оборот и география за 2024 год')]),
('read','Бри Рид','Snag','snag-portrait','Посадка как основа сообщества',
'Snag строит коммуникацию вокруг разнообразия тел и доступной размерной сетки. В официальной публикации марта 2026 года Бригитта (Бри) Рид представлена как CEO; здесь использован её настоящий портрет из этой публикации. Интервью бизнес-школе Эдинбургского университета показывает значение прямого общения с покупателями для развития бренда.',
'Для покупателя ценность такой модели — возможность увидеть вещь на разных фигурах и подобрать посадку по понятным критериям. Для компании обратная связь становится источником продуктовых решений. Однако сообщения в сообществе и повторные продажи — разные показатели: активность сама по себе не доказывает прибыльность.',
'Редакционный разбор: расширить размеры недостаточно. Нужны проверка лекал, фотографии на разных телах, устойчивые поставки каждого размера и поддержка при ошибочном выборе. Обещание инклюзивности проверяется опытом получения и носки вещи.',
'Что проверять: наличие всех размеров, возвраты и причины отказов, время ответа поддержки, повторные заказы. Неподтверждённая оценка личного состояния здесь не приводится.',
[('https://snagtights.com/blogs/news/women-who-lead-snag','Snag: Women Who Lead, 06.03.2026'),('https://www.business-school.ed.ac.uk/about/news/inspiring-people-brie-read-on-success-without-outside-investment','Интервью Бри Рид, University of Edinburgh')]),
('wolford','Wolford','Премиальный трикотаж','wolford-3','Цена образа и цена розничной сети',
'Wolford соединяет технические характеристики трикотажа с модной фотографией, узнаваемой подачей и специализированной розницей. Для такого бренда покупатель приобретает и свойства изделия, и предсказуемый опыт: фактуру, посадку, упаковку, консультацию.',
'В сообщении от 16 марта 2026 года Wolford объявила неаудированную выручку за 2025 год: 76 млн евро против 88 млн в 2024-м. Розница и аутлеты снизились на 27%, онлайн — на 15%, опт вырос на 17%. Эти цифры описывают динамику каналов, а не личное состояние основателей.',
'Редакционный разбор: сильный визуальный образ не отменяет расходов на торговую сеть. Собственный магазин даёт контроль над сервисом, но требует достаточного оборота. Опт расширяет присутствие через партнёров, при этом бренд делится торговой маржой и контролем представления.',
'Что проверять: сопоставимость периодов, закрытия магазинов, долю каждого канала и статус отчётности. Неаудированная выручка не позволяет сделать вывод о чистой прибыли.',
[('https://company.wolford.com/wolford-ag-announces-sales-figures-for-fiscal-year-2025/','Wolford: предварительные продажи за 2025 год')]),
('falke','Пауль и Франц-Петер Фальке','FALKE','falke-people','Долгий горизонт семейного производства',
'Официальная история FALKE начинается с вязальной мастерской Франца Фальке-Роэна в 1895 году. В 1990-м управление перешло к четвёртому поколению — Паулю и Францу-Петеру Фальке. На фотографии именно они: подпись не подменяет современных руководителей историческими основателями.',
'Хронология компании показывает постепенное накопление производственных компетенций и расширение ассортимента. Семейная преемственность — факт истории, но не автоматическая гарантия качества каждой модели. Качество всё равно проверяется по материалу, конструкции и эксплуатации.',
'Редакционный разбор: долгий горизонт позволяет инвестировать в навыки, оборудование и стабильные отношения с поставщиками. Вместе с преимуществом возникает задача обновления: как сохранить узнаваемость и отвечать на новые запросы без распыления ассортимента.',
'Что проверять: доступность базовых моделей, прозрачность состава, контроль качества и способность обновлять производство. Дата основания не заменяет данные о сегодняшней эффективности.',
[('https://www.falke.com/uk_en/about-us/history/','FALKE: официальная история и портрет владельцев')]),
('swedish','Линн Фрисингер и Надя Форсберг','Swedish Stockings','swedish-factory','Материал, дизайн и проверяемое обещание',
'Swedish Stockings основана в 2013 году. Компания описывает производство в Италии и использование переработанных и натуральных волокон. Фотография вязального оборудования взята из её собственного рассказа о производстве; это не случайная фабрика из фотобанка.',
'Экологическая коммуникация требует точности: происхождение сырья, доля переработанного материала, срок службы и способы обращения с отходами — разные вопросы. Заявления самой компании следует отличать от независимого исследования жизненного цикла изделия.',
'Редакционный разбор: желание купить вещь появляется на пересечении дизайна, посадки и убедительного объяснения происхождения. Переработанная нить сама по себе не делает изделие бесконечно долговечным и не означает, что готовую смешанную ткань можно переработать любым способом.',
'Что проверять: состав конкретной модели, документы по сырью, условия программы сбора и измеримые результаты. Здесь корпоративные заявления не выдаются за независимую сертификацию.',
[('https://swedishstockings.com/pages/about-us','Swedish Stockings: основательницы и производство')]),
('golden','Golden Lady Company','Golden Lady, Omsa, Sisi, Filodoro','golden-factory','Масштаб и портфель брендов',
'Официальная хронология Golden Lady начинается в 1966 году. В неё входят приобретения Sisi в 1987-м, Omsa в 1992-м, Filodoro и Philippe Matignon в 2003-м. Так формировался портфель марок с разными позициями на рынке.',
'Одна производственная группа может обслуживать разные ожидания покупателя: повседневную базу, модные рисунки, разные цены и каналы продаж. Общий владелец при этом не означает одинаковые состав, лекала или свойства всех моделей.',
'Редакционный разбор: масштаб потенциально распределяет затраты на оборудование, закупки и логистику между большим объёмом. Но слишком много похожих позиций усложняет запасы и может размывать различия между брендами. Сила портфеля зависит от ясной роли каждой марки.',
'Что проверять: ассортимент по каналам, сезонность, наличие размеров и различия между заявленным позиционированием и реальным изделием. Фотография показывает производство Golden Lady, а не условный текстильный цех.',
[('https://www.goldenladycompany.com/en/companys-history','Golden Lady Company: история группы')])]
biz=intro('Люди, производство, экономика','За каждой парой —<br>целая индустрия.','Как из тонкой нити получается большой бизнес: семь подробных кейсов, реальные портреты и производства, устройство себестоимости и риски роста.')
biz+=toc([('business-chain','Путь изделия'),('business-cases','Семь кейсов'),('homuth','Урок SRTX'),('unit-economics','Экономика пары')])
biz+='<section class="portal-container portal-section" id="business-chain"><div class="editorial-section-title"><h2>От волокна<br>до повторной покупки.</h2><p>Выберите этап. У каждого своя задача, расходы и способы потерять качество.</p></div><div class="scenario-selector" data-scenarios="business"><div class="editorial-filters">'+''.join(f'<button data-scenario="{k}">{t}</button>' for k,t in [('yarn','01 / Нить'),('knit','02 / Вязание'),('finish','03 / Отделка'),('retail','04 / Продажа'),('repeat','05 / Повтор')])+'</div><div class="scenario-result choice-result" aria-live="polite"></div></div></section>'
biz+='<section class="portal-container business-cases" id="business-cases"><div class="editorial-section-title"><h2>Разные пути.<br>Конкретные решения.</h2><p>Факты — по источникам рядом с кейсом. Выводы о бизнес-модели — редакционный разбор.</p></div>'
data=[]
for id,name,company,img,heading,fact,context,analysis,risk,refs in cases:
 biz+=f'<article class="business-case" id="profile-{id}"><div class="business-visual">'+photo(img)+f'<p class="portal-eyebrow">{company}</p><h2>{name}</h2></div><div class="business-copy"><h3>{heading}</h3>'+p(fact)+p(context)+p(analysis)+f'<div class="case-question">{risk}</div><div class="case-sources">'+''.join(link(u,t) for u,t in refs)+'</div></div></article>'
 data.append(dict(id=id,name=name,company=company,story=fact,figure=context,image=M[img]['image']))
biz+='</section>'
biz+='<section class="portal-section editorial-band" id="homuth"><div class="portal-container reading-body"><p class="portal-eyebrow">Контрпример · SRTX / Sheertex</p><h2>Технология не заменяет<br>устойчивую экономику.</h2><p>Высокопрочный трикотаж Sheertex привлёк внимание к проблеме недолговечности тонких колготок. Но технологическая идея и финансовая устойчивость — разные стороны бизнеса.</p><p>По сообщению юридической фирмы Miller Thomson, 26 февраля 2026 года A.Y.K. приобрела SRTX в рамках одобренной судом сделки. Механизм позволил сохранить действующий бизнес и ключевые активы, отделив прежние обязательства. Цена в этом сообщении не раскрыта.</p><p>Редакционный вывод: при оценке инновации нужно смотреть не только на демонстрацию прочности, но и на капитальные затраты, загрузку оборудования, стоимость выпуска и способность финансировать масштабирование. Из самого факта сделки нельзя вывести будущую прибыльность или личное состояние основательницы Кэтрин Хомут.</p>'+link('https://www.millerthomson.com/en/deals-cases/a-y-k-acquires-srtx-inc/','Первичный источник: сообщение о закрытии сделки')+'</div></section>'
biz+='''<section class="portal-section portal-container" id="unit-economics"><div class="editorial-section-title"><h2>Сколько остаётся<br>с одной продажи?</h2><p>Учебная модель с вашими числами. Начальные значения условные, это не статистика рынка и не прогноз дохода.</p></div><form id="unit-form" class="choice-form"><label>Цена продажи, ₽<input name="price" type="number" min="0" max="1000000" value="1200" required></label><label>Закупка / выпуск пары, ₽<input name="cost" type="number" min="0" max="1000000" value="400" required></label><label>Комиссия канала, %<input name="fee" type="number" min="0" max="100" value="15" required></label><label>Логистика на заказ, ₽<input name="shipping" type="number" min="0" max="1000000" value="120" required></label><label>Реклама на заказ, ₽<input name="ads" type="number" min="0" max="1000000" value="180" required></label><label>Резерв на возвраты, ₽<input name="returns" type="number" min="0" max="1000000" value="60" required></label></form><div id="unit-result" class="choice-result" aria-live="polite"></div><p class="tonko-note">Вклад на покрытие = цена − выпуск − комиссия − логистика − реклама − резерв. Это не чистая прибыль: здесь нет постоянных расходов, налогов, финансирования и полной модели возвратов.</p></section>'''
page('business.html','Индустрия: люди, бренды и экономика колготок','Подробные кейсы SPANX, Oniverse, Snag, Wolford, FALKE, Swedish Stockings, Golden Lady и SRTX. Реальные фотографии и калькулятор экономики.',biz)
(S/'data/business.js').write_text('window.BUSINESS_DATA = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')

src=intro('Редакционная политика','Можно проверить.','История брендов, происхождение изображений и границы наших выводов. Обновлено 15 ноября 2026 года.')
src+=toc([('history','Истории брендов'),('photography','Фотографии'),('logos','Логотипы')])
src+='<section class="portal-container portal-section"><div class="reading-body"><h2>Что считается источником</h2><p>Для историй компаний приоритет имеют корпоративные архивы, отчёты, публикации участников событий и музейные коллекции. Ссылки размещены рядом с соответствующими утверждениями.</p><p>Факт из источника и редакционная интерпретация разделены. Финансовые показатели сопровождаются периодом и пояснением: выручка, оценка компании и личное состояние — разные величины.</p><p>В каталоге 43 бренда. Исторические справки 15 брендов сверены отдельно; остальные явно помечены как требующие проверки. Наличие бренда в каталоге не означает, что каждая деталь его истории уже подтверждена.</p></div></section>'
src+='<section class="portal-section portal-section-soft" id="history"><div class="portal-container"><h2>Реестр проверки историй</h2><div class="tonko-source-register" id="history-register"></div></div></section>'
src+='<section class="portal-section portal-container" id="photography"><div class="reading-body"><h2>Новая фотоколлекция</h2><p>Фотоориентиры — студийные каталоги, прозрачность ткани, выразительные силуэты, мужские образы и детали изделия. Google Картинки использовались для поиска; поисковая система не является автором изображения или лицензией.</p><p>В этом выпуске используются фотографии с сайтов Wolford, Tezenis, Nike, Swedish Stockings, FALKE, Oniverse, Golden Lady, Snag, Activskin и из публикации Virgin о SPANX. Они подписаны по источнику. Обозначение «материал правообладателя» описывает происхождение, а не свободную лицензию; разрешение на повторное использование отдельно не подтверждено.</p><p>Часть изображений предоставлена владельцем проекта как визуальная подборка. Для них авторство и исходная публикация пока не установлены; бренд и личность модели не приписываются. Небольшие исходники не увеличиваются до размера полноэкранной фотографии. Кадры с водяными знаками фотобанков не включены.</p><p>Портреты и производственные фотографии имеют конкретные подписи. Современный кадр рядом с историческим текстом не выдаётся за фотографию той эпохи. Генерированные изображения в этой подборке не использовались.</p><p>По вопросам атрибуции или удаления изображения используйте <a href="https://github.com/big-arch/TOHKO/issues" target="_blank" rel="noopener">обращение в репозитории</a>, указав страницу и название фотографии.</p></div><ol class="tonko-source-list" id="photo-register"></ol></section>'
src+='<section class="portal-section portal-section-soft" id="logos"><div class="portal-container"><h2>Оригинальные логотипы</h2><p>Файлы получены из официальных сайтов брендов. Товарные знаки принадлежат правообладателям; размещение не означает партнёрство с проектом.</p><ul class="tonko-source-list" id="logo-register"></ul></div></section>'
page('sources.html','Источники и фотографии','Источники историй брендов, происхождение фото, оригинальные логотипы и редакционная политика.',src,'<script src="data/brands.js"></script><script src="data/brand-research.js"></script>')

# Replace every legacy photograph still used by the supporting articles.
history=S/'history.html';text=history.read_text(encoding='utf-8')
historic=[('adrian-city','Современный образ Adrian с колготками. Это иллюстрация сегодняшнего гардероба, не исторический костюм.'),('wolford-3','Современный тонкий трикотаж Wolford. Иллюстрация материала, не фотография разработки 1935 года.'),('golden-history','Архивная фотография Golden Lady из истории компании. Не иллюстрация военного производства DuPont.'),('conte-waist','Современный пример растяжения верхней части изделия из подборки проекта.'),('patterns','Современные фантазийные узоры из подборки проекта. Не архив 1960-х.'),('swedish-rib','Современная коллекция Swedish Stockings: цвет и фактура.')]
counter=iter(historic)
# The separately generated brand archive owns its figures. Only replace legacy chronology photos.
text=re.sub(r'<figure\b(?![^>]*class="[^"]*\bexperience-photo\b)[^>]*>.*?</figure>',lambda match:photo(*(next(counter))),text,flags=re.S)
history.write_text(text,encoding='utf-8')
for filename,id,caption in [('atlas.html','toe','Мысок и фактура: деталь изделия из подборки проекта.'),('nylon.html','wolford-3','Полиамидный трикотаж в современной модели Wolford Individual 10.')]:
 f=S/filename;t=f.read_text(encoding='utf-8')
 # Replace the image and its own caption together to keep attribution accurate.
 t=re.sub(r'<figure\b[^>]*>.*?assets/images/.*?</figure>',lambda _:photo(id,caption),t,count=1,flags=re.S)
 if 'assets/images/' in t:
  t=re.sub(r'<img\b[^>]*src="assets/images/[^"]+"[^>]*>',lambda _:photo(id,caption),t,count=1)
 f.write_text(t,encoding='utf-8')

for f in S.glob('*.html'):
 t=f.read_text(encoding='utf-8')
 t=re.sub(r'\s*<small>Энциклопедия</small>','',t)
 t=t.replace('Гид и DEN','Как выбрать').replace('Энциклопедия DEN','Как выбрать')
 t=t.replace('по вашим визуальным ориентирам — с крупными оригиналами и примерами из присланной коллекции','с каталогами брендов и выразительными образами')
 if 'tonko.css' in t and 'editorial.css' not in t:t=t.replace('</head>','<link rel="stylesheet" href="editorial.css"></head>')
 if f.name in ('brand.html','brands.html'):
  if 'features.css' not in t:t=t.replace('<link rel="stylesheet" href="tonko.css">','<link rel="stylesheet" href="features.css"><link rel="stylesheet" href="tonko.css">')
  if 'src="tools.js"' not in t:t=t.replace('<script src="tonko.js">','<script src="tools.js"></script><script src="tonko.js">')
 # Consistent short navigation labels on the older supporting pages.
 t=t.replace('href="brands.html">Бренды и модели','href="brands.html">Бренды').replace('href="lookbook.html">Фотогалерея','href="lookbook.html">Галерея').replace('href="business.html">Бизнес','href="business.html">Индустрия')
 f.write_text(t,encoding='utf-8')

(S/'data/photos.js').write_text('window.PHOTO_DATA = '+json.dumps([m for m in M.values() if m['category'] not in ('business','archive')],ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
# Legacy search uses this array; the new gallery reads the same manifest directly.
t=(S/'tools.js').read_text(encoding='utf-8').replace("['Энциклопедия DEN','Плотность, материалы, размеры и уход'","['Как выбрать: мастерская','Подбор пары, сравнение DEN, викторина, конструкция и уход'")
t=t.replace('Люди и деньги в индустрии','Люди и экономика индустрии')
(S/'tools.js').write_text(t,encoding='utf-8')
print('Editorial pages built; media:',len(M))
